mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM trips
    WHERE id = #{tripId}
      AND is_deleted = 0
)

mapper.update:
UPDATE trips
SET wallet_reflect_resolved = 1
WHERE id = #{tripId}

mapper.select:
SELECT balance_amount
FROM wallet
WHERE user_id = #{userId}

SELECT onboarding_shown_at
FROM users
WHERE id = #{userId}

mapper.update:
UPDATE trips
SET status = 'ARCHIVED'
WHERE id = #{tripId}
  AND user_id = #{userId}
  AND (status = 'ENDED' OR end_date < CURRENT_DATE)
  AND is_deleted = 0

UPDATE trip_countries
SET target_budget = #{localTravelTarget}
WHERE id = #{tripCountryId}
  AND is_deleted = 0

UPDATE trips
SET total_target_amount = #{totalTargetAmount}
WHERE id = #{tripId}
  AND is_deleted = 0

UPDATE saving_plans
SET monthly_amount = #{monthlyAmount}
WHERE id = #{id}
  AND is_deleted = 0
